 quiz:[['業務用語集が主に答える問いは？',['サーバーの容量は？','この言葉は何を意味する？','誰が昨日ログインした？'],1,'業務の言葉を同じ意味で使うための説明です。'],['元項目の変更で影響するレポートを探すには？',['リネージをたどる','名前順に並べる','データを削除する'],0,'加工と利用先のつながりから影響を調べます。'],['カタログ導入後に必要な活動は？',['一度登録したら終了','列名だけ集める','定義の責任者と更新手順を決める'],2,'説明もデータと同じく維持が必要です。']],
 exercise:[{q:'「月間購入顧客数」の説明を、対象・期間・除外条件・責任者を含めて書いてください。',a:'当月に出荷した注文の顧客を顧客ID単位で重複なく数える。取消のみの注文は除外。月末締め、翌営業日更新。定義の承認者は販売企画責任者。'},{q:'注文の金額項目を変更するとき、どの利用先を確認しますか。',a:'受注→売上集計→BI→経営レポートの流れに加え、請求処理、個別の表計算、外部への配布を確認する。変換条件と変更の適用日も記録する。'}],
